/*
If you want to aim high, aim high
Don't let that studying and grades consume you
Just live life young
******************************
If I'm the sun, you're the moon
Because when I go up, you go down
*******************************
I'm working for the day I will surpass you
https://www.a2oj.com/Ladder16.html
*/
import java.util.*;
import java.io.*;
import java.math.*;

   public class x1342E
   {
      static long MOD = 998244353L;
      public static void main(String omkar[]) throws Exception
      {
         BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));  
         StringTokenizer st = new StringTokenizer(infile.readLine());
         int N = Integer.parseInt(st.nextToken());
         long lmao = Long.parseLong(st.nextToken());
         if(lmao >= N)
            System.out.println(0);
         else
         {
            int K = (int)lmao;
            int C = N-K;
            fac = new long[200001];
            invfac = new long[200001];
            fac[0] = 1L;   invfac[0] = 1L;
            for(int i=1; i <= 200000; i++)
            {
               fac[i] = (fac[i-1]*i)%MOD;
               invfac[i] = power(fac[i], MOD-2, MOD);
            }
            long res = power(C, N, MOD);
            for(int e=1; e < C; e++)
            {
               long temp = power(C-e, N, MOD);
               temp = (temp*nCr(e, C))%MOD;
               if(e%2 == 1)
                  res = (res-temp+MOD)%MOD;
               else
                  res = (res+temp)%MOD;
            }
            res = (res*nCr(C, N))%MOD;
            if(K > 0)
               res = (2*res)%MOD;
            System.out.println(res);
         }
      }
      static long[] fac;
      static long[] invfac;
      public static long nCr(int a, int b)
      {
         long res = fac[b];
         res = (res*invfac[a])%MOD;
         return (res*invfac[b-a])%MOD;
      }
      public static long power(long x, long y, long p) 
      { 
          long res = 1L;      
          x = x % p;  
          while (y > 0) 
          { 
              if((y & 1)==1) 
                  res = (res * x) % p; 
              y = y >> 1;  
              x = (x * x) % p;  
          } 
          return res; 
      } 
   }
